#ifdef HAVE_WCHAR_H
#include <wchar.h>
#endif

#define MAX_RECURSION	100

static int
pm_list(const char *start, const char *end, const char c, int flags)
{
	const char *p = start;
	char rangeStart = '\0', nextRangeStart;
	int match = 1, nomatch = 0;

	(void)flags;

	if ((*p == '!' || *p == '^') && p < end) {
		match = 0;
		nomatch = 1;
		++p;
	}

	while (p < end) {
		nextRangeStart = '\0';
		switch (*p) {
		case '-':

			if ((rangeStart == '\0') || (p == end - 1)) {
				if (*p == c)
					return (match);
			} else {
				char rangeEnd = *++p;
				if (rangeEnd == '\\')
					rangeEnd = *++p;
				if ((rangeStart <= c) && (c <= rangeEnd))
					return (match);
			}
			break;
		case '\\':
			++p;

		default:
			if (*p == c)
				return (match);
			nextRangeStart = *p;
		}
		rangeStart = nextRangeStart;
		++p;
	}
	return (nomatch);
}

static int
pm_list_w(const wchar_t *start, const wchar_t *end, const wchar_t c, int flags)
{
	const wchar_t *p = start;
	wchar_t rangeStart = L'\0', nextRangeStart;
	int match = 1, nomatch = 0;

	(void)flags;

	if ((*p == L'!' || *p == L'^') && p < end) {
		match = 0;
		nomatch = 1;
		++p;
	}

	while (p < end) {
		nextRangeStart = L'\0';
		switch (*p) {
		case L'-':

			if ((rangeStart == L'\0') || (p == end - 1)) {
				if (*p == c)
					return (match);
			} else {
				wchar_t rangeEnd = *++p;
				if (rangeEnd == L'\\')
					rangeEnd = *++p;
				if ((rangeStart <= c) && (c <= rangeEnd))
					return (match);
			}
			break;
		case L'\\':
			++p;

		default:
			if (*p == c)
				return (match);
			nextRangeStart = *p;
		}
		rangeStart = nextRangeStart;
		++p;
	}
	return (nomatch);
}

static const char *
pm_slashskip(const char *s) {
	while ((*s == '/')
	    || (s[0] == '.' && s[1] == '/')
	    || (s[0] == '.' && s[1] == '\0'))
		++s;
	return (s);
}

static const wchar_t *
pm_slashskip_w(const wchar_t *s) {
	while ((*s == L'/')
	    || (s[0] == L'.' && s[1] == L'/')
	    || (s[0] == L'.' && s[1] == L'\0'))
		++s;
	return (s);
}

static int
pm(const char *p, const char *s, int flags, int depth)
{
	const char *end;
	int r;

	if (depth > MAX_RECURSION)
		return (-1);

	if (s[0] == '.' && s[1] == '/')
		s = pm_slashskip(s + 1);
	if (p[0] == '.' && p[1] == '/')
		p = pm_slashskip(p + 1);

	for (;;) {
		switch (*p) {
		case '\0':
			if (s[0] == '/') {
				if (flags & PATHMATCH_NO_ANCHOR_END)
					return (1);

				s = pm_slashskip(s);
			}
			return (*s == '\0');
		case '?':

			if (*s == '\0')
				return (0);
			break;
		case '*':

			while (*p == '*')
				++p;

			if (*p == '\0')
				return (1);
			while (*s) {
				r = pm(p, s, flags, depth + 1);
				if (r)
					return (r);
				++s;
			}
			return (0);
		case '[':

			end = p + 1;
			while (*end != '\0' && *end != ']') {
				if (*end == '\\' && end[1] != '\0')
					++end;
				++end;
			}
			if (*end == ']') {

				if (*s == '\0' || !pm_list(p + 1, end, *s, flags))
					return (0);
				p = end;
				break;
			} else

				if (*p != *s)
					return (0);
			break;
		case '\\':

			if (p[1] == '\0') {
				if (*s != '\\')
					return (0);
			} else {
				++p;
				if (*p != *s)
					return (0);
			}
			break;
		case '/':
			if (*s != '/' && *s != '\0')
				return (0);

			p = pm_slashskip(p);
			s = pm_slashskip(s);
			if (*p == '\0' && (flags & PATHMATCH_NO_ANCHOR_END))
				return (1);
			--p;
			--s;
			break;
		case '$':

			if (p[1] == '\0' && (flags & PATHMATCH_NO_ANCHOR_END)){

				return (*pm_slashskip(s) == '\0');
			}

		default:
			if (*p != *s)
				return (0);
			break;
		}
		++p;
		++s;
	}
}

static int
pm_w(const wchar_t *p, const wchar_t *s, int flags, int depth)
{
	const wchar_t *end;
	int r;

	if (depth > MAX_RECURSION)
		return (-1);

	if (s[0] == L'.' && s[1] == L'/')
		s = pm_slashskip_w(s + 1);
	if (p[0] == L'.' && p[1] == L'/')
		p = pm_slashskip_w(p + 1);

	for (;;) {
		switch (*p) {
		case L'\0':
			if (s[0] == L'/') {
				if (flags & PATHMATCH_NO_ANCHOR_END)
					return (1);

				s = pm_slashskip_w(s);
			}
			return (*s == L'\0');
		case L'?':

			if (*s == L'\0')
				return (0);
			break;
		case L'*':

			while (*p == L'*')
				++p;

			if (*p == L'\0')
				return (1);
			while (*s) {
				r = pm_w(p, s, flags, depth + 1);
				if (r)
					return (r);
				++s;
			}
			return (0);
		case L'[':

			end = p + 1;
			while (*end != L'\0' && *end != L']') {
				if (*end == L'\\' && end[1] != L'\0')
					++end;
				++end;
			}
			if (*end == L']') {

				if (!pm_list_w(p + 1, end, *s, flags))
					return (0);
				p = end;
				break;
			} else

				if (*p != *s)
					return (0);
			break;
		case L'\\':

			if (p[1] == L'\0') {
				if (*s != L'\\')
					return (0);
			} else {
				++p;
				if (*p != *s)
					return (0);
			}
			break;
		case L'/':
			if (*s != L'/' && *s != L'\0')
				return (0);

			p = pm_slashskip_w(p);
			s = pm_slashskip_w(s);
			if (*p == L'\0' && (flags & PATHMATCH_NO_ANCHOR_END))
				return (1);
			--p;
			--s;
			break;
		case L'$':

			if (p[1] == L'\0' && (flags & PATHMATCH_NO_ANCHOR_END)){

				return (*pm_slashskip_w(s) == L'\0');
			}

		default:
			if (*p != *s)
				return (0);
			break;
		}
		++p;
		++s;
	}
}

int
__archive_pathmatch(const char *p, const char *s, int flags)
{

	if (p == NULL || *p == '\0')
		return (s == NULL || *s == '\0');
	else if (s == NULL)
		return (0);

	if ((flags & PATHMATCH_NO_ANCHOR_START) && *p == '^') {
		++p;
		flags &= ~PATHMATCH_NO_ANCHOR_START;
	}

	if (*p == '/' && *s != '/')
		return (0);

	if (*p == '*' || *p == '/') {
		while (*p == '/')
			++p;
		while (*s == '/')
			++s;
		return (pm(p, s, flags, 0));
	}

	if (flags & PATHMATCH_NO_ANCHOR_START) {
		for ( ; s != NULL; s = strchr(s, '/')) {
			int r;

			if (*s == '/')
				s++;
			r = pm(p, s, flags, 0);
			if (r)
				return (r);
		}
		return (0);
	}

	return (pm(p, s, flags, 0));
}

int
__archive_pathmatch_w(const wchar_t *p, const wchar_t *s, int flags)
{

	if (p == NULL || *p == L'\0')
		return (s == NULL || *s == L'\0');
	else if (s == NULL)
		return (0);

	if ((flags & PATHMATCH_NO_ANCHOR_START) && *p == L'^') {
		++p;
		flags &= ~PATHMATCH_NO_ANCHOR_START;
	}

	if (*p == L'/' && *s != L'/')
		return (0);

	if (*p == L'*' || *p == L'/') {
		while (*p == L'/')
			++p;
		while (*s == L'/')
			++s;
		return (pm_w(p, s, flags, 0));
	}

	if (flags & PATHMATCH_NO_ANCHOR_START) {
		for ( ; s != NULL; s = wcschr(s, L'/')) {
			int r;

			if (*s == L'/')
				s++;
			r = pm_w(p, s, flags, 0);
			if (r)
				return (r);
		}
		return (0);
	}

	return (pm_w(p, s, flags, 0));
}

