#define Ppmd_See_Update(p) do {						\
	if ((p)->Shift < PPMD_PERIOD_BITS && --(p)->Count == 0) {	\
		(p)->Summ <<= 1;					\
		(p)->Count = (Byte)(3 << (p)->Shift++);			\
    	}								\
} while (0)

