#define PPMD_SetAllBitsIn256Bytes(p) do {				\
	unsigned j;							\
	for (j = 0; j < 256 / sizeof(p[0]); j += 8) {			\
		p[j+7] = p[j+6] = p[j+5] = p[j+4] =			\
		    p[j+3] = p[j+2] = p[j+1] = p[j+0] = ~(size_t)0;	\
	}								\
} while (0)

