struct rpm {
	int data_reached;
};
#define RPM_LEAD_SIZE		96
#define RPM_MIN_HEAD_SIZE	16

static int	rpm_bidder_bid(struct archive_read_filter_bidder *,
		    struct archive_read_filter *);
static int	rpm_bidder_init(struct archive_read_filter *);

