int
archive_read_support_filter_lzip(struct archive *_a)
{
	struct archive_read *a = (struct archive_read *)_a;

	if (__archive_read_register_bidder(a, NULL, "lzip",
				&lzip_bidder_vtable) != ARCHIVE_OK)
		return (ARCHIVE_FATAL);

#if HAVE_LZMA_H && HAVE_LIBLZMA
	return (ARCHIVE_OK);
#else
	archive_set_error(_a, ARCHIVE_ERRNO_MISC,
	    "Using external lzip program for lzip decompression");
	return (ARCHIVE_WARN);
#endif
}

static int
xz_bidder_bid(struct archive_read_filter_bidder *self,
    struct archive_read_filter *filter)
{
	const unsigned char *buffer;

	(void)self;

	buffer = __archive_read_filter_ahead(filter, 6, NULL);
	if (buffer == NULL)
		return (0);

	if (memcmp(buffer, "\xFD\x37\x7A\x58\x5A\x00", 6) != 0)
		return (0);

	return (48);
}

static int
lzma_bidder_bid(struct archive_read_filter_bidder *self,
    struct archive_read_filter *filter)
{
	const unsigned char *buffer;
	uint32_t dicsize;
	uint64_t uncompressed_size;
	int bits_checked;

	(void)self;

	buffer = __archive_read_filter_ahead(filter, 14, NULL);
	if (buffer == NULL)
		return (0);

	bits_checked = 0;
	if (buffer[0] > (4 * 5 + 4) * 9 + 8)
		return (0);

	if (buffer[0] == 0x5d || buffer[0] == 0x5e)
		bits_checked += 8;

	uncompressed_size = archive_le64dec(buffer+5);
	if (uncompressed_size == (uint64_t)ARCHIVE_LITERAL_LL(-1))
		bits_checked += 64;

	dicsize = archive_le32dec(buffer+1);
	switch (dicsize) {
	case 0x00001000:
	case 0x00002000:
	case 0x00004000:
	case 0x00008000:
	case 0x00010000:

	case 0x00020000:
	case 0x00040000:
	case 0x00080000:

	case 0x00100000:

	case 0x00200000:

	case 0x00400000:

	case 0x00800000:

	case 0x01000000:

	case 0x02000000:

	case 0x04000000:

	case 0x08000000:
		bits_checked += 32;
		break;
	default:

		if (dicsize <= 0x03F00000 && dicsize >= 0x00300000 &&
		    (dicsize & ((1 << 20)-1)) == 0 &&
		    bits_checked == 8 + 64) {
			bits_checked += 32;
			break;
		}

		return (0);
	}

	return (bits_checked);
}

static int
lzip_has_member(struct archive_read_filter *filter)
{
	const unsigned char *buffer;
	int bits_checked;
	int log2dic;

	buffer = __archive_read_filter_ahead(filter, 6, NULL);
	if (buffer == NULL)
		return (0);

	bits_checked = 0;
	if (memcmp(buffer, "LZIP", 4) != 0)
		return (0);
	bits_checked += 32;

	if (buffer[4] != 0 && buffer[4] != 1)
		return (0);
	bits_checked += 8;

	log2dic = buffer[5] & 0x1f;
	if (log2dic < 12 || log2dic > 29)
		return (0);
	bits_checked += 8;

	return (bits_checked);
}

static int
lzip_bidder_bid(struct archive_read_filter_bidder *self,
    struct archive_read_filter *filter)
{

	(void)self;
	return (lzip_has_member(filter));
}

